ALTER TABLE "macro_dependency_heads" ADD CONSTRAINT "macro_dependency_hea_version_id_d3e7ca58_fk_macro_dep" FOREIGN KEY ("version_id") REFERENCES "macro_dependency_versions" ("id") DEFERRABLE INITIALLY DEFERRED;
